const catalog=new Map(pairs),lower=new Map(pairs.map(([a,b])=>[a.toLowerCase(),b]));
function tr(value){const text=String(value);if(language==='en'||!text)return text;const clean=text.trim();let result=catalog.get(clean);if(result===undefined&&lower.has(clean.toLowerCase())){result=lower.get(clean.toLowerCase());if(clean===clean.toUpperCase())result=result.toUpperCase();}
 if(result===undefined){const rules=[
 [/^SECTOR (\d+) \/ 8$/,m=>'SEKTOR '+m[1]+' / 8'],[/^SYSTEMS (\d+)\/3$/,m=>'SISTEM '+m[1]+'/3'],[/^Parts (\d+)\/3$/,m=>'Komponen '+m[1]+'/3'],[/^Guardian (\d+\/\d+)$/,m=>'Penjaga '+m[1]],[/^Find (?!\d+ components for )(.+)$/,m=>'Cari '+tr(m[1])],[/^PLAY: CONTINUE SECTOR (\d+)$/,m=>'MULAI: LANJUTKAN SEKTOR '+m[1]],[/^(\w+) gate$/,m=>'Gerbang '+m[1]],
 [/^Repair the faulty ([A-Z]+) circuit: replace its wrong chip and reconnect the broken wire\.$/,m=>'Perbaiki rangkaian '+m[1]+' yang rusak: ganti cip yang salah dan sambungkan kembali kabel yang terputus.'],[/^Predict every output of the ([A-Z]+) system\. Drag 0 or 1 into each answer socket\.$/,m=>'Prediksi setiap keluaran sistem '+m[1]+'. Seret 0 atau 1 ke setiap soket jawaban.'],[/^Build ([A-Z]+) logic for every input combination to power this system\.$/,m=>'Rakit logika '+m[1]+' untuk setiap kombinasi masukan agar sistem ini aktif.'],
 [/^(.+) is already repaired\.$/,m=>tr(m[1])+' sudah diperbaiki.'],[/^Current shield phase needs (.+)\.$/,m=>'Fase perisai saat ini memerlukan '+tr(m[1])+'.'],[/^Find (\d+) components for (.+)\.$/,m=>'Cari '+m[1]+' komponen untuk '+tr(m[2])+'.'],[/^(.+) repaired$/,m=>tr(m[1])+' diperbaiki'],[/^(\d+)\/3 systems online\.$/,m=>m[1]+'/3 sistem aktif.'],[/^Needs (\d+) parts$/,m=>'Perlu '+m[1]+' komponen'],[/^Component recovered: (\d+)\/3$/,m=>'Komponen ditemukan: '+m[1]+'/3'],[/^Try again! (\d+) lives remaining\.$/,m=>'Coba lagi! Sisa '+m[1]+' nyawa.'],[/^SHIELD RESTORED$/,()=> 'PERISAI PULIH'],[/^\[ONLINE\] (.+)$/,m=>'[AKTIF] '+tr(m[1])],[/^(.+) \[E\]$/,m=>tr(m[1])+' [E]'],
 [/^Parts recovered: (\d+)\/3$/,m=>'Komponen terkumpul: '+m[1]+'/3'],[/^This system needs (\d+)\. Failed attempts consume nothing\.$/,m=>'Sistem ini memerlukan '+m[1]+'. Percobaan salah tidak menghabiskan komponen.'],[/^Tests: (\d+)$/,m=>'Percobaan: '+m[1]],[/^Hints: (\d+)$/,m=>'Petunjuk: '+m[1]],[/^(\d+) tests?$/,m=>m[1]+' percobaan'],[/^(\d+) hints?$/,m=>m[1]+' petunjuk'],[/^\+(\d+) score$/,m=>'+'+m[1]+' skor'],[/^For (.+), the expected output is (\d)\.$/,m=>'Untuk '+m[1]+', keluaran yang benar adalah '+m[2]+'.'],[/^Output for (.+)$/,m=>'Keluaran untuk '+m[1]],[/^Output (\d)$/,m=>'Keluaran '+m[1]],
 [/^WIRE$/,()=> 'KABEL'],[/^Drag (.+) into a socket\. Gold = IN, cyan = OUT\.$/,m=>'Seret '+m[1]+' ke soket. Emas = MASUK, sian = KELUAR.']
 ];for(const[pattern,render]of rules){const match=clean.match(pattern);if(match){result=render(match);break;}}
 }
 if(result===undefined){for(const sep of ['\n',' • ','  —  ',' •'])if(clean.includes(sep)){result=clean.split(sep).map(tr).join(sep);break;}}
 return result===undefined?text:text.slice(0,text.indexOf(clean))+result+text.slice(text.indexOf(clean)+clean.length);
}
const nativeText=new WeakMap(),roots=new Map();let revision=0;
function translated(node,source,write){const old=nativeText.get(node),record=old&&source===old.rendered?old:{source,rendered:source};const rendered=tr(record.source);if(source!==rendered)write(rendered);record.rendered=rendered;nativeText.set(node,record);}
function scan(root){const entry=roots.get(root);if(!entry)return;entry.observer.disconnect();const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode())if(!['STYLE','SCRIPT'].includes(node.parentElement?.tagName))translated(node,node.nodeValue,value=>node.nodeValue=value);for(const el of [root,...root.querySelectorAll('[aria-label],[title],[alt],[placeholder]')]){let attrs=entry.attributes.get(el);if(!attrs){attrs=new Map();entry.attributes.set(el,attrs);}for(const attr of ['aria-label','title','alt','placeholder'])if(el.hasAttribute(attr)){const value=el.getAttribute(attr),old=attrs.get(attr),original=old&&value===old.rendered?old.source:value,newValue=tr(original);if(newValue!==value)el.setAttribute(attr,newValue);attrs.set(attr,{source:original,rendered:newValue});}}entry.dirty=false;entry.revision=revision;entry.observer.observe(root,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['aria-label','title','alt','placeholder']});}
function watch(root){if(!roots.has(root)){const entry={dirty:true,revision:-1,attributes:new WeakMap()};entry.observer=new MutationObserver(()=>entry.dirty=true);roots.set(root,entry);}scan(root);}
const service=localeOwner.__crLocale={tr,watch,get language(){return language;},setLanguage(value){if(!['id','en'].includes(value))return;language=value;revision++;try{localStorage.setItem('cr-language',value);}catch{}document.documentElement.lang=value;},frame(scene){if(typeof document==='undefined')return;document.documentElement.lang=language;for(const id of ['cr-workbench','cr-touch-controls','cr-journey','cr-navigation','cr-mobile-browser']){const root=document.getElementById(id);if(root&&!roots.has(root))watch(root);}for(const[root,entry]of roots){if(!root.isConnected){entry.observer.disconnect();roots.delete(root);}else if(entry.dirty||entry.revision!==revision)scan(root);}const data=localeOwner.getGameData().layouts.find(s=>s.name===scene.getName());for(const object of data?.objects??[])if(object.type==='TextObject::Text')for(const instance of scene.getObjects(object.name))translated(instance,instance.getString(),value=>instance.setString(value));}};

