 const button=root.querySelector('button'),status=root.querySelector('[role=status]');document.body.append(root);
 root.querySelector('style').textContent+='html[data-cr-mobile-browser=true] input,html[data-cr-mobile-browser=true] textarea,html[data-cr-mobile-browser=true] [contenteditable=true]{user-select:text;-webkit-user-select:text;-webkit-touch-callout:default;touch-action:auto}';
