function translated(node,source,write){const old=nativeText.get(node),record=old&&source===old.rendered?old:{source,rendered:source};const rendered=tr(record.source);if(source!==rendered)write(rendered);record.rendered=rendered;nativeText.set(node,record);}
function scan(root){const entry=roots.get(root);if(!entry)return;entry.observer.disconnect();const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode())if(!['STYLE','SCRIPT'].includes(node.parentElement?.tagName))translated(node,node.nodeValue,value=>node.nodeValue=value);for(const el of [root,...root.querySelectorAll('[aria-label],[title],[alt],[placeholder]')]){let attrs=entry.attributes.get(el);if(!attrs){attrs=new Map();entry.attributes.set(el,attrs);}for(const attr of ['aria-label','title','alt','placeholder'])if(el.hasAttribute(attr)){const value=el.getAttribute(attr),old=attrs.get(attr),original=old&&value===old.rendered?old.source:value,newValue=tr(original);if(newValue!==value)el.setAttribute(attr,newValue);attrs.set(attr,{source:original,rendered:newValue});}}entry.dirty=false;entry.revision=revision;entry.observer.observe(root,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['aria-label','title','alt','placeholder']});}
function watch(root){if(!roots.has(root)){const entry={dirty:true,revision:-1,attributes:new WeakMap()};entry.observer=new MutationObserver(()=>entry.dirty=true);roots.set(root,entry);}scan(root);}
const service=localeOwner.__crLocale={tr,watch,get language(){return language;},setLanguage(value){if(!['id','en'].includes(value))return;language=value;revision++;try{localStorage.setItem('cr-language',value);}catch{}document.documentElement.lang=value;},frame(scene){if(typeof document==='undefined')return;document.documentElement.lang=language;for(const id of ['cr-workbench','cr-touch-controls','cr-journey','cr-navigation','cr-mobile-browser']){const root=document.getElementById(id);if(root&&!roots.has(root))watch(root);}for(const[root,entry]of roots){if(!root.isConnected){entry.observer.disconnect();roots.delete(root);}else if(entry.dirty||entry.revision!==revision)scan(root);}const data=localeOwner.getGameData().layouts.find(s=>s.name===scene.getName());for(const object of data?.objects??[])if(object.type==='TextObject::Text')for(const instance of scene.getObjects(object.name))translated(instance,instance.getString(),value=>instance.setString(value));}};

